const fs = require('fs');
const input = fs.readFileSync(0, 'utf-8').trim().split('\n');

const n = parseInt(input[0]) + 1;
const total = input[1].split(' ').map(Number).reduce((sum, e) => sum + e, 0);
let count = 0;

for (let i = 1; i <= 5; i++) {
    if ((i + total) % n !== 1) {
        count++;
    }
}

console.log(count);

